import React from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import './App.css';
import StyleGuide from './components/StyleGuide';

function App() {
  return (
    <Router>
      <div className="App">
        <Routes>
          <Route path="/" element={
            <div style={{ 
              padding: '40px', 
              textAlign: 'center', 
              background: '#FAFBFC', 
              minHeight: '100vh',
              display: 'flex',
              flexDirection: 'column',
              justifyContent: 'center',
              alignItems: 'center'
            }}>
              <h1 style={{ color: '#0A2540', marginBottom: '20px' }}>POS System Components</h1>
              <p style={{ color: '#6B7C93', marginBottom: '30px' }}>React component development in progress</p>
              <a 
                href="/styleguide" 
                style={{ 
                  background: '#6A7FFF', 
                  color: 'white', 
                  padding: '12px 24px', 
                  borderRadius: '8px', 
                  textDecoration: 'none',
                  fontWeight: '500'
                }}
              >
                View Style Guide
              </a>
            </div>
          } />
          <Route path="/styleguide" element={<StyleGuide />} />
        </Routes>
      </div>
    </Router>
  );
}

export default App;
